<?php
require __DIR__.'/common.php';$user=require_role($pdo,['admin','staff']);check_csrf();$m=strtoupper($_SERVER['REQUEST_METHOD']??'GET');$d=json_input();
try{if($m==='POST'){$orderId=trim((string)($d['orderId']??''));$rating=(int)($d['rating']??0);$customer=trim((string)($d['customer']??''))?:'Khách hàng';$content=trim((string)($d['content']??''));if($orderId===''||$rating<1||$rating>5)respond(['ok'=>false,'message'=>'Thông tin đánh giá không hợp lệ.'],422);$q=$pdo->prepare('SELECT status FROM orders WHERE order_id=? LIMIT 1');$q->execute([$orderId]);$o=$q->fetch();if(!$o||$o['status']!=='Đã thanh toán')respond(['ok'=>false,'message'=>'Chỉ ghi nhận đánh giá cho đơn đã thanh toán.'],422);$c=$pdo->prepare('SELECT COUNT(*) FROM reviews WHERE order_id=?');$c->execute([$orderId]);if((int)$c->fetchColumn()>0)respond(['ok'=>false,'message'=>'Đơn hàng này đã có đánh giá.'],409);$id='DG'.date('YmdHis').random_int(100,999);$s=$pdo->prepare('INSERT INTO reviews(review_id,order_id,customer_name,rating,content,entered_by,created_at) VALUES(?,?,?,?,?,?,NOW())');$s->execute([$id,$orderId,$customer,$rating,$content,$user['id']]);respond(['ok'=>true,'id'=>$id,'message'=>'Đã ghi nhận đánh giá.']);}if($m==='DELETE'){if($user['role']!=='admin')respond(['ok'=>false,'message'=>'Chỉ Admin được xóa đánh giá.'],403);$id=trim((string)($_GET['id']??''));if($id==='')respond(['ok'=>false,'message'=>'Thiếu mã đánh giá.'],422);$pdo->prepare('DELETE FROM reviews WHERE review_id=?')->execute([$id]);respond(['ok'=>true,'message'=>'Đã xóa đánh giá.']);}respond(['ok'=>false,'message'=>'Phương thức không được hỗ trợ.'],405);}catch(Throwable $e){error_log($e->__toString());respond(['ok'=>false,'message'=>'Không thể xử lý đánh giá.'],500);}
